<div class="table-shell" id="sales-results" aria-busy="false"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Sale</th><th>Buyer</th><th>Date</th><th>Pigs</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($sales as $sale): ?><tr><td>#<?=e(sale_reference((int) $sale['sale_id']))?></td><td class="fw-bold"><?=e($sale['buyer_name'])?></td><td><?=e($sale['sale_date'])?></td><td><?=e($sale['pig_count'])?></td><td>₱<?=number_format((float)$sale['total_amount'],2)?></td><td class="text-end"><a class="btn btn-sm btn-outline-secondary" href="view.php?id=<?=(int)$sale['sale_id']?>">View receipt</a></td></tr><?php endforeach; ?><?php if(!$sales): ?><tr><td colspan="6" class="text-center text-muted py-5">No sales found.</td></tr><?php endif; ?></tbody></table></div></div>
